// 1. Obter texto do CSV retornado pelo nó HTTP anterior
let csvText = '';
if (typeof $input.first().json.data === 'string') {
  csvText = $input.first().json.data;
} else if (typeof $input.first().json === 'string') {
  csvText = $input.first().json;
} else {
  csvText = JSON.stringify($input.first().json);
}

// Fallback de segurança se o download falhar ou vier vazio
if (!csvText || !csvText.includes('perfil')) {
  csvText = `perfil,produto,minimo,rentabilidade
Conservador,Poupança,100,6.2%
Conservador,CDB Liquidez Diária,1000,12.5%
Conservador,Tesouro Selic,500,13.0%
Moderado,CDB Prefixado,1000,14.0%
Moderado,Fundo Multimercado,5000,16.0%
Moderado,Tesouro IPCA+,1000,IPCA+6.0%
Arrojado,Ações ETF,500,Variável
Arrojado,Fundo de Ações,10000,Variável
Arrojado,Criptomoedas,100,Variável`;
}

// 2. Parser do CSV de Opções de Investimento
const linhasCsv = csvText.trim().split(/\r?\n/);
const catalogo = [];
for (let i = 1; i < linhasCsv.length; i++) {
  const cols = linhasCsv[i].split(',').map(c => c.trim());
  if (cols.length >= 4) {
    catalogo.push({
      perfil: cols[0],
      produto: cols[1],
      minimo: parseFloat(cols[2]) || 0,
      rentabilidade: cols[3]
    });
  }
}

// 3. Obter a lista de clientes enviada ao Webhook
const webhookData = $('Webhook - Receber Clientes').first().json;
const webhookBody = webhookData.body || webhookData;
const clientes = Array.isArray(webhookBody) ? webhookBody : (webhookBody.clientes || [webhookBody]);

function converterSaldo(valor) {
  if (typeof valor === 'number') return valor;
  const limpo = String(valor || '0').replace(/[^0-9,-]/g, '').replace(',', '.');
  return parseFloat(limpo) || 0;
}

const itemsParaIA = [];

// 4. Cruzar dados e montar prompt customizado para a IA por cliente
for (const cliente of clientes) {
  if (!cliente || !cliente.nome) continue;

  const perfil = (cliente.perfil || 'Conservador').trim();
  const saldoNumerico = converterSaldo(cliente.saldo);

  const produtosPerfil = catalogo.filter(p => p.perfil.toLowerCase() === perfil.toLowerCase());
  const produtosCompativeis = produtosPerfil.filter(p => saldoNumerico >= p.minimo);
  const produtoPrincipal = produtosCompativeis.length > 0
    ? produtosCompativeis[produtosCompativeis.length - 1]
    : (produtosPerfil[0] || { produto: 'Tesouro Selic', rentabilidade: '13.0%', minimo: 500 });

  const catalogoResumido = produtosCompativeis.map(p => `${p.produto} (Rentabilidade: ${p.rentabilidade}, Aporte mínimo: R$ ${p.minimo})`).join('; ');

  // Prompt com engenharia de contexto para o modelo LLM
  const prompt = `Você é um Consultor Financeiro de Investimentos sênior e atencioso.
Crie uma mensagem de recomendação de investimentos personalizada, clara, persuasiva e humanizada para o cliente com os dados abaixo:

- Nome: ${cliente.nome}
- Perfil do Investidor: ${perfil}
- Saldo Disponível para Aplicação: ${cliente.saldo}
- Produto Principal Recomendado: ${produtoPrincipal.produto} (${produtoPrincipal.rentabilidade})
- Outras opções compatíveis com o perfil e saldo: ${catalogoResumido}

Diretrizes obrigatórias:
1. Cumprimente o cliente pelo primeiro nome em tom consultivo e amigável.
2. Justifique a indicação do produto principal com base no perfil (${perfil === 'Conservador' ? 'segurança e liquidez' : perfil === 'Moderado' ? 'equilíbrio e rentabilidade' : 'alto potencial de valorização'}).
3. Apresente os dados de rentabilidade de forma acessível.
4. Finalize com um convite cordial para esclarecer dúvidas e iniciar o investimento.
5. Tamanho máximo: 2 a 3 parágrafos objetivos. Use emojis com moderação.`;

  itemsParaIA.push({
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      saldo_numerico: saldoNumerico,
      perfil: perfil,
      recomendacao_principal: produtoPrincipal,
      produtos_compativeis: produtosCompativeis.map(p => p.produto),
      prompt_ia: prompt
    }
  });
}

return itemsParaIA;

// Mescla o retorno da IA com os dados originais do cliente
const resultados = [];
for (let i = 0; i < $items().length; i++) {
  const itemOriginal = $('Cruzar Dados e Preparar Contexto IA').all()[i].json;
  const respostaIa = $items()[i].json.text || $items()[i].json.response || $items()[i].json;

  resultados.push({
    json: {
      nome: itemOriginal.nome,
      email: itemOriginal.email,
      saldo: itemOriginal.saldo,
      perfil: itemOriginal.perfil,
      produto_recomendado: itemOriginal.recomendacao_principal.produto,
      rentabilidade: itemOriginal.recomendacao_principal.rentabilidade,
      mensagem_personalizada: typeof respostaIa === 'string' ? respostaIa : JSON.stringify(respostaIa),
      tipo_mensagem: "Gerada por IA Generativa (Google Gemini)",
      data_processamento: new Date().toISOString()
    }
  });
}

return resultados;

